#!/usr/bin/env node
// Generates src/overlay-help.generated.ts (gap sweep G4, hub #3000): every
// table of docs/keybindings.md "Overlay Key Reference (generated)", which the
// TUI writes from its OVERLAY_HELP_ROUTES catalog. The keybindings help lists
// the open overlay's table in its Contextual view and every table in All
// Commands, as the TUI's help covers "every overlay that owns its own keys".
//
//   node scripts/overlay-help.mjs          # rewrite the generated file
//   node scripts/overlay-help.mjs --check  # exit 1 when it is stale
// tests/overlay-help.test.mjs runs the check.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const DOC_PATH = join(root, '..', 'docs', 'keybindings.md');
export const OUT_PATH = join(root, 'src', 'overlay-help.generated.ts');

const cells = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split(/(?<!\\)\|/).map((c) => c.trim());
const unticks = (s) => s.replace(/`([^`]*)`/g, '$1').replace(/\\\|/g, '|');

/** The overlay tables: `{ name, rows: [{ keys, action, detail }] }`, in document order. */
export function parseOverlayTables(md) {
  const lines = md.split('\n');
  const start = lines.findIndex((l) => /^## Overlay Key Reference \(generated\)/.test(l));
  if (start < 0) throw new Error('docs/keybindings.md has no "Overlay Key Reference (generated)" section');
  const out = [];
  let cur = null;
  let header = null;
  for (let i = start + 1; i < lines.length; i++) {
    const l = lines[i];
    if (/^## /.test(l)) break;
    const h = /^### (.+)$/.exec(l);
    if (h) { cur = { name: h[1].trim(), rows: [] }; out.push(cur); header = null; continue; }
    if (!cur || !l.trim().startsWith('|')) { if (!l.trim().startsWith('|')) header = null; continue; }
    const c = cells(l);
    if (c.every((x) => /^-+$/.test(x))) continue;
    if (header === null) { header = c.map((x) => x.toLowerCase()); continue; }
    const at = (name) => header.indexOf(name);
    const keys = unticks(c[at('keys') >= 0 ? at('keys') : 0] ?? '');
    const action = unticks(c[at('action') >= 0 ? at('action') : 1] ?? '');
    const detailAt = at('what it does') >= 0 ? at('what it does') : at('description');
    const detail = detailAt >= 0 ? unticks(c[detailAt] ?? '') : '';
    if (keys) cur.rows.push({ keys, action, detail });
  }
  return out.filter((t) => t.rows.length > 0);
}

export function render(tables) {
  return `// Generated by scripts/overlay-help.mjs from docs/keybindings.md
// "Overlay Key Reference (generated)". Do not edit; run \`node scripts/overlay-help.mjs\`.

export interface OverlayKeyRow { keys: string; action: string; detail: string }
export interface OverlayTable { name: string; rows: readonly OverlayKeyRow[] }

export const OVERLAY_TABLES: readonly OverlayTable[] = [
${tables.map((t) => `  { name: ${JSON.stringify(t.name)}, rows: [\n${t.rows.map((r) => `    ${JSON.stringify(r)},`).join('\n')}\n  ] },`).join('\n')}
];
`;
}

export function generated() {
  return render(parseOverlayTables(readFileSync(DOC_PATH, 'utf8')));
}

export function isFresh() {
  try { return readFileSync(OUT_PATH, 'utf8') === generated(); } catch { return false; }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (process.argv.includes('--check')) {
    if (!isFresh()) { console.error('overlay-help: src/overlay-help.generated.ts is stale; run node scripts/overlay-help.mjs'); process.exit(1); }
    console.log('overlay-help: generated file is current');
  } else {
    writeFileSync(OUT_PATH, generated());
    console.log('overlay-help: wrote src/overlay-help.generated.ts');
  }
}
